mapper.sql:
WHERE 1=1
AND batch_id=#{batchId}
AND account_id=#{accountId}
AND cycle_start BETWEEN #{cycleStart} AND #{cycleEnd}
AND publish_date>=#{start}
AND publish_date<=#{end}
AND plan_type=#{planType}
AND content_type=#{contentType}
AND (LOCATE(LOWER(#{account}),LOWER(account_id))>0 OR LOCATE(LOWER(#{account}),LOWER(account_name))>0)
AND LOCATE(LOWER(#{um}),LOWER(owner_um))>0
AND organization=#{organization}
AND platform=#{platform}
AND lifecycle_stage=#{lifecycle}
AND account_type=#{accountType}
AND followers>=#{followersMin}
AND followers<=#{followersMax}
AND account_id IN #{a}
AND batch_id IN #{b}

mapper.select:
SELECT * FROM godp_planning_item_read 
  AND  IN #{k}
  AND id>#{afterId}
  ORDER BY idpublish_date DESC,id DESC
  LIMIT #{limit}

mapper.sql:
WHERE 1=1
  AND week_start>=#{startWeek}
  AND week_start<=#{endDate}
  AND (LOCATE(LOWER(#{batchQuery}),LOWER(batch_code))>0 OR CAST(id AS CHAR(32))=#{batchQuery})

WHERE 1=1
  AND (LOCATE(LOWER(#{batch}),LOWER(task_name))>0 OR LOCATE(LOWER(#{batch}),LOWER(batch_code))>0)
  AND LOCATE(LOWER(#{creator}),LOWER(created_by))>0
  AND publish_date>=#{dateStart}
  AND publish_date<=#{dateEnd}
  AND content_status IN #{s}

mapper.select:
SELECT f.payload FROM godp_planning_failure f JOIN godp_planning_batch_read b ON b.id=f.batch_id WHERE 1=1
  AND b.id=#{batchId}
  AND f.account_key=#{accountId}
  AND b.week_start BETWEEN #{cycleStart} AND #{cycleEnd}
  AND b.plan_type=#{planType}
  ORDER BY b.created_at DESC,f.account_key
